var _markdown = "\n\n`extensions/Shader.h` · **仅 SA** · 继承 `DynamicResource`\n\n## 加载与开关 [#加载与开关]\n\n构造时可直接指定 hlsl / fxc。设备丢失时走 DynamicResource 生命周期。\n\n<CodeBlockTabs defaultValue=\"签名\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"签名\">\n      签名\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"示例\">\n      示例\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"签名\">\n    ```cpp\n    Shader(std::string const& Filename, bool bDebug = false);\n    void Load();\n    void Unload();\n    void Enable();\n    void Disable();\n    void EnablePSForRwImRender();\n    void DisablePSForRwImRender();\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"示例\">\n    ```cpp\n    #ifdef GTASA\n    #include \"extensions/Shader.h\"\n\n    static plugin::Shader g_shader(PLUGIN_PATH(\"fx\\\\simple.hlsl\"));\n\n    g_shader.Enable();\n    // ...\n    g_shader.Disable();\n    #endif\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n## 绑定纹理 [#绑定纹理]\n\n绑到寄存器 `idx`。\n\n<CodeBlockTabs defaultValue=\"签名\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"签名\">\n      签名\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"示例\">\n      示例\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"签名\">\n    ```cpp\n    void PackTexture(RxD3D9InstanceData* mesh, unsigned int idx);\n    void PackTexture(RpMaterial* material, unsigned int idx);\n    void PackTexture(RwTexture* texture, unsigned int idx);\n    void SetMeshTexture(RxD3D9InstanceData* mesh, unsigned int idx);\n    void SetMaterialTexture(RpMaterial* material, unsigned int idx);\n    void SetTexture(RwTexture* texture, unsigned int idx);\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"示例\">\n    ```cpp\n    g_shader.PackTexture(tex, 0);\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n## 塞常量参数 [#塞常量参数]\n\n结构体注意 **16 字节对齐** 与补零。\n\n<CodeBlockTabs defaultValue=\"签名\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"签名\">\n      签名\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"示例\">\n      示例\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"签名\">\n    ```cpp\n    template <class T>\n    bool PackPSParameters(T& parameters, unsigned int offset = 0);\n\n    template <class T>\n    bool PackVSParameters(T& parameters, unsigned int offset = 0);\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"示例\">\n    ```cpp\n    struct Ps {\n        float color[4];\n    } ps{};\n    g_shader.PackPSParameters(ps);\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n## 源码与二进制 [#源码与二进制]\n\n构造内会 `Load`。可另存为 fxc。\n\n<CodeBlockTabs defaultValue=\"签名\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"签名\">\n      签名\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"示例\">\n      示例\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"签名\">\n    ```cpp\n    bool LoadFromSource(std::ifstream& file, bool bDebug);\n    bool LoadFromBinary(std::ifstream& file);\n    void Load();\n    bool SaveToBinary();\n    bool SaveToBinary(std::string const& Filename);\n    bool WriteToBinaryFile(std::ofstream& file);\n    static char* CompileShaderFromString(char const* str, char const* Entrypoint, char const* Version, bool bDebug);\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"示例\">\n    ```cpp\n    g_shader.SaveToBinary(PLUGIN_PATH(\"fx\\\\simple.fxc\"));\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n## 矩阵与画矩形 [#矩阵与画矩形]\n\n<CodeBlockTabs defaultValue=\"签名\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"签名\">\n      签名\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"示例\">\n      示例\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"签名\">\n    ```cpp\n    static void GetWorldViewProj(\n        RpAtomic* atomic,\n        D3DMATRIX* world,\n        D3DMATRIX* view,\n        D3DMATRIX* proj,\n        D3DMATRIX* wvp);\n\n    static void DrawRect(float left, float top, float right, float bottom);\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"示例\">\n    ```cpp\n    D3DMATRIX world{}, view{}, proj{}, wvp{};\n    plugin::Shader::GetWorldViewProj(atomic, &world, &view, &proj, &wvp);\n    plugin::Shader::DrawRect(0.0f, 0.0f, 1.0f, 1.0f);\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n";
